# In-place quicksort, pivot = last element, on the sorted array; count swaps under three partition schemes
def quicksort(a, partition):
    st = {'swap_calls': 0, 'changing_swaps': 0, 'comparisons': 0}
    def swap(i, j):
        st['swap_calls'] += 1
        if a[i] != a[j]: st['changing_swaps'] += 1   # a swap that actually changes the array
        a[i], a[j] = a[j], a[i]
    def less(u, v, strict=False):
        st['comparisons'] += 1
        return u < v if strict else u <= v
    def qs(lo, hi):
        if lo < hi:
            p = partition(a, lo, hi, swap, less)
            qs(lo, p - 1); qs(p + 1, hi)
    qs(0, len(a) - 1)
    return st
def lomuto(a, lo, hi, swap, less):          # CLRS PARTITION
    x, i = a[hi], lo - 1
    for j in range(lo, hi):
        if less(a[j], x):
            i += 1; swap(i, j)
    swap(i + 1, hi); return i + 1
def lomuto_skip(a, lo, hi, swap, less):     # same, but never swaps an element with itself
    x, i = a[hi], lo - 1
    for j in range(lo, hi):
        if less(a[j], x):
            i += 1
            if i != j: swap(i, j)
    if i + 1 != hi: swap(i + 1, hi)
    return i + 1
def two_pointer(a, lo, hi, swap, less):     # swaps only a (larger-on-left, smaller-on-right) pair
    x, i, j = a[hi], lo, hi - 1
    while True:
        while i <= j and less(a[i], x, True): i += 1
        while j >= i and less(x, a[j], True): j -= 1
        if i >= j: break
        swap(i, j); i += 1; j -= 1
    if i != hi: swap(i, hi)
    return i
import random; random.seed(0)
for name, part in [('Lomuto (CLRS)', lomuto), ('Lomuto, skip self-swaps', lomuto_skip), ('two-pointer', two_pointer)]:
    for _ in range(2000):                   # sanity: each scheme really sorts
        r = [random.randint(0, 9) for _ in range(random.randint(0, 12))]; s = r[:]; quicksort(s, part); assert s == sorted(r)
    a = [60, 70, 80, 90, 100]
    st = quicksort(a, part)
    print(f'{name:24s} -> {a}  swap statements={st["swap_calls"]:2d}  array-changing swaps={st["changing_swaps"]}  comparisons={st["comparisons"]}')
